INSERT INTO churn_type (type_id, type_name, description) VALUES ('T01', '구독료 부담형', '이탈 이유 중 "돈"에 관한 불만(구독이 구매·할부보다 비싸고 매달 고정비가 나감)을 한데 묶어 총비용·고정비로 이름 붙임');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T02', '해지·이사 장벽형', '위약금·철거비·해지 절차 지연처럼 해지하거나 이사할 때 드는 조건 부담을 묶어 이름 붙임 (기존 2번 + 이사 이슈 통합)');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T03', '재계약·갈아타기 갈등형', '약정 만료 전후의 재계약 압박, 요금 인상, 신모델 출시 후 아쉬움이 모두 "계약 갱신 시점"에 걸려 있어 이름 붙임 (기존 8·9번 통합)');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T04', '사용 빈도 저하·방치형', '제습기처럼 거의 쓰지 않는데 구독료만 나가는 경우라 "사용 빈도 저하·방치"로 이름 붙임 (기존 7번 대체, 근거 적음)');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T05', '케어 부실·피해형', '* 방문은 했지만 청소가 부실하거나 뒷정리·점검이 미흡했다는 "케어 결과물의 품질" 불만이라 이름 붙임 * 케어를 받은 뒤에 누수·고장·파손 등 멀쩡하던 제품에 문제가 생겼다는 "케어 후 피해"가 공통이라 이름 붙임');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T06', '방문 일정 불편형', '* 약속 시간 지연, 일방 취소, 미방문처럼 방문 자체가 약속대로 이행되지 않은 경우라 이름 붙임 (기존 3번 계승) * 평일 위주·예약 가능 일정 부족 등 고객이 시간을 맞추기 어렵다는 "일정 조율의 부담"이라 이름 붙임');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T07', '매니저 품질 불만형', '* 불친절, 말없이 냉동실 열기, 고객 물건 함부로 다루기 등 담당자의 말투·행동 문제라 이름 붙임 (기존 4번 계승) * 매니저가 자주 바뀌고 숙련도·설명 수준이 사람마다 다르다는 불만이라 "교체·전문성 편차"로 이름 붙임');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T08', '영업 압박형', '케어 때마다 신제품·추가상품을 권하는 영업 행위 때문에 불편하다는 불만이라 이름 붙임');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T09', '제품 고장·성능 불만형', '케어와 무관하게 제품 자체의 소음·얼음·버튼 문제나 잦은 고장을 겪는 경우라 이름 붙임 (기존 5번 계승)');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('T10', 'AS·고객센터 불만형', '문제가 생긴 뒤 AS 분리 접수, 연락 두절, 수리 지연, 책임 떠넘기기 등 "사후 대응"이 불만이라 이름 붙임 (기존 6번 일부)');
INSERT INTO churn_type (type_id, type_name, description) VALUES ('유형없음', '유형 없음', '유형 확정 기준(SHAP 비중 20% 이상)에 못 미치는 경우의 pseudo-type');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T01-A', 1, 'T01', '정보제공', '구독 vs 구매 총비용 비교 카드', '가입 후 6개월마다 납부 내역을 정리해 구매가와 비교할 수 있게 안내', '알림톡', 'N', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '가입 후 6개월마다', '[비교표 보기] / [납부 내역]', '지금까지 낸 금액·남은 금액·약정 종료 시 인수 금액을 구매가와 나란히 안내. 월 요금만 강조하지 않음', 'N', 20, '[["months_since_start", ">=", 6]]', '고객님, 지금까지 낸 구독료를 정리했어요', '["paid_total", "months_since_start", "end_date"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T01-B', 2, 'T01', '정보제공', '프로모션 종료 사전 고지', '프로모션 종료 30일 전 정상 요금 전환을 미리 고지', '알림톡', 'N', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '프로모션 종료 30일 전', '[요금제 비교하기] / [상세보기]', '현재 금액·변경 후 금액·변경일을 나란히 안내하고 더 낮은 요금제 확인 방법을 함께 안내', 'N', 20, '[["days_to_promo_end", ">=", 0, "required"], ["days_to_promo_end", "<=", 30, "required"]]', '고객님, 프로모션 종료 후 구독료가 바뀌어요', '["monthly_fee", "promo_end_date"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T01-C', 3, 'T01', '혜택제안', '놓친 할인 점검', '아직 적용되지 않은 할인(동시 구독·제휴카드 등)을 찾아 신청하도록 안내', '친구톡', 'Y', 'N', NULL, '고객 메시지', 'Y', 0, '감소', '미적용 할인 감지 시', '[할인 신청하기] / [조건 보기]', '미적용 할인 항목별 월 절감액과 합계, 신청 방법 안내. 제목 앞 (광고) 표기 ※ 고객 문구에 ''총 비용''이나 ''위약금'' 단어를 넣어, 할인을 적용해도 총 비용·위약금 조건이 바뀌지 않는지 앱에서 확인하도록 안내한다', 'N', 10, '[["unapplied_discount_yn", "==", "Y", "required"]]', '(광고) 고객님, 매달 더 아낄 수 있는 할인이 있어요', NULL, 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T01-D', 4, 'T01', '제품조치', '요금제·케어 구성 다운그레이드 안내', '케어 주기 등 구성을 바꿔 월 요금을 낮추는 선택지 안내(신규 정책)', '친구톡', 'Y', 'N', NULL, '고객 메시지', 'Y', 0, '감소', '해지 문의·요금 불만 접수 시', '[금액 낮추기] / [구성 비교]', '현재 구성과 변경 후 구성의 월 요금, 계약 기간 중 변경 가능 횟수를 안내. 해지 대신 조정 선택지임을 중립적으로 안내. (광고) 표기', 'Y', 30, '[["voc_fee_or_cancel_cnt_30d", ">=", 1]]', '(광고) 고객님, 케어 주기만 바꿔도 요금이 내려가요', '["monthly_fee"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T01-E', 5, 'T01', '혜택제안', '장기 구독 캐시백·구간 할인', '유지 36개월 도달 고객에게 장기 구독 감사 혜택 제공(신규 정책). 20,000원은 가정값', '친구톡', 'Y', 'N', NULL, '고객 메시지', 'Y', 20000, '없음', '유지 36개월 도달 시', '[리워드 받기] / [혜택 상세]', '구독 기간과 감사 혜택(포인트·추가 구독 할인)을 안내. 금액은 원가 확정 후 결정. (광고) 표기', 'Y', 30, '[["months_since_start", ">=", 36, "required"]]', '(광고) 고객님, 오래 함께해 주셔서 감사해요', '["months_since_start"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T02-A', 6, 'T02', '정보제공', '케어 해지 시 잔여 청구 기준 사전 안내', '해지·가입 상담 시 잔여 청구 기준을 사전 고지(압박으로 읽힐 수 있어 메시지 미발송)', '상담·앱', 'N', 'N', NULL, '상담·앱 안내', 'Y', 0, '없음', '가입 상담·해지 상담 시', '(앱) [계약 정보 보기]', '고객 발송 메시지 없음. 상담사용 필수 고지: 현재 계약 기간·해지 시 잔여 청구 개월·자동 연장일', 'N', 20, NULL, '고객님, 케어 서비스 해지 시 남은 기간 청구 기준을 안내드립니다', '["end_date", "care_renewal_date"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T02-B', 7, 'T02', '담당자조치', '해지·이사 전담 상담 연결과 처리 상태 안내', '이사 신호 감지 시 전담 상담사를 연결(유형요약 F8: 보류 검토 의견 있음)', '알림톡', 'N', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '주소 변경, 방문 일정 반복 변경, 상담 중 ‘이사’ 언급 감지 시', '[전담 상담 예약] / [이사 안내 보기]', '철거·재설치 지원 대상 여부, 새 집 설치 가능 여부, 해지 시 총비용 비교를 안내하고 전담 상담 예약으로 연결', 'N', 10, '[["move_signal_yn", "==", "Y"]]', '고객님, 이사 준비 중이신가요?', NULL, 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T03-A', 8, 'T03', '정보제공', '만기 4개월 전 선택지 비교 안내', '만기 124일 전 선택지를 비교해 안내', '알림톡', 'N', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '만기 124일 전', '[4가지 비교하기] / [상담 연결]', '재구독 할인·제품 인수 금액·신모델 재구독·해지 비용 4가지를 한 번에 비교해 안내', 'N', 20, '[["days_to_end", ">=", 0, "required"], ["days_to_end", "<=", 124, "required"]]', '고객님, 구독 만료가 다가오고 있어요', '["end_date", "days_to_end"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T03-B', 9, 'T03', '제품조치', '만기 전 신모델 갈아타기 할인 선제안', '후속 모델이 나온 만기 6개월 이내 고객에게 같은 요금 갈아타기 제안', '친구톡', 'Y', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '후속 모델 출시 + 만기 6개월 이내', '[신모델 보기] / [갈아타기 신청]', '지금 쓰는 모델·신모델·월 요금 변동 없음·혜택 기한을 안내. (광고) 표기', 'N', 30, '[["new_model_released_yn", "==", "Y", "required"], ["days_to_end", ">=", 0, "required"], ["days_to_end", "<=", 180, "required"]]', '(광고) 고객님, 새로 나온 모델로 바꿔 보세요', '["end_date"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T03-C', 10, 'T03', '정보제공', '단종 예정 모델 조기 알림과 우선 교체 혜택', '단종 예정 모델 고객에게 부품 지원 종료를 미리 알리고 교체 방법 안내', '알림톡', 'N', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '부품 지원 종료 90일 전', '[교체 안내 보기] / [상세보기]', '부품 지원 종료 예정일과 종료 후 영향을 안내. 교체 혜택은 본문이 아니라 버튼 뒤 앱 화면에서 안내', 'N', 20, '[["model_discontinued_yn", "==", "Y", "required"]]', '고객님, 사용 중인 제품의 부품 지원이 종료될 예정이에요', NULL, 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T04-A', 11, 'T04', '정보제공', '사용 로그 기반 활용 알림', '오래 안 쓴 제품을 계절에 맞게 쓰도록 사용법 안내', '친구톡', 'Y', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '30일 이상 미사용 + 계절·날씨 조건', '[사용법 영상] / [자동 운전 켜기]', '마지막 사용일과 계절·날씨에 맞는 추천 사용법·영상을 안내. (광고) 표기 ※ 고객 문구에 기간(N주·N일)이나 횟수를 쓰지 말고, 요금·할인·구독료를 언급하지 않는다', 'N', 30, '[["days_since_last_use", ">=", 30]]', '(광고) 고객님, 제품을 이렇게 활용해 보세요', '["days_since_last_use"]', 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T04-B', 12, 'T04', '정보제공', '미사용 기능 리포트', '품목별 미사용률·미사용 기능 Top 5를 분기 1회 집계해 전달', '내부 전달', 'N', 'Y', '제품기획팀, 구독상품기획팀', '전사 개선', 'N', 0, '없음', '분기 1회', '[전달하기]', '분기 집계 리포트로 Agent 후보가 아님', 'N', 90, NULL, NULL, NULL, 'Y');
INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T04-C', 13, 'T04', '정보제공', '미소진 케어 혜택 안내', '계약 연도 종료 60일 전 남은 케어를 소진하도록 안내', '알림톡', 'N', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '계약 연도 종료 60일 전, 잔여 케어 1회 이상', '[방문 날짜 예약] / [케어 내역 보기]', '올해 받은 케어 횟수·남은 횟수(요금 포함)·사용 기한과 예약 방법을 안내', 'N', 20, '[["days_to_contract_year_end", ">=", 0], ["days_to_contract_year_end", "<=", 60], ["remaining_care_cnt", ">=", 1, "required"]]', '고객님, 올해 받을 수 있는 케어가 남았어요', '["remaining_care_cnt", "contract_year_end_date"]', 'Y');
