INSERT INTO solution_catalog (solution_id, seq_no, type_id, solution_category, solution_name, solution_detail, channel, ad_yn, internal_forward_yn, forward_dept, delivery_kind, agent_selectable_yn, offer_cost, fee_impact, trigger_note, buttons, message_hint, new_policy_yn, priority, eligibility, customer_title, message_items, active_yn) VALUES ('S-T08-B', 29, 'T08', '혜택제안', '추가 구독 혜택은 앱으로만 안내', '케어 완료 3일 후 방문과 분리해 앱 중심 혜택 안내. 영업 압박 고객에게 광고성 메시지가 역효과일 수 있음', '친구톡', 'Y', 'N', NULL, '고객 메시지', 'Y', 0, '없음', '케어 완료 3일 후 (방문과 분리)', '[혜택 보기] / [관심 없음]', '추가 구독 혜택(결합 할인 등)은 앱에서만 안내하고 방문 때는 권유하지 않음을 안내. 관심 없음 버튼 포함. (광고) 표기', 'N', 30, '[["days_since_last_care", ">=", 3, "required"], ["days_since_last_care", "<=", 14, "required"]]', '(광고) 고객님만을 위한 추가 구독 혜택이 있어요', NULL, 'Y');
